-- Crear backup de la tabla actual
CREATE TABLE BlogPost_backup AS SELECT * FROM BlogPost;

-- Eliminar la tabla actual
DROP TABLE BlogPost;

-- Crear nueva tabla BlogPost simplificada
CREATE TABLE BlogPost (
    Id TEXT PRIMARY KEY,
    Title TEXT NOT NULL,
    Summary TEXT,
    Slug TEXT NOT NULL UNIQUE,
    IsPublished INTEGER NOT NULL DEFAULT 0,
    IsFeatured INTEGER NOT NULL DEFAULT 0,
    Views INTEGER NOT NULL DEFAULT 0,
    CreatedAt INTEGER NOT NULL,
    UpdatedAt INTEGER,
    PublishedAt INTEGER,
    AuthorId INTEGER NOT NULL,
    CategoryId TEXT,
    Tags TEXT, -- JSON array of tags
    FOREIGN KEY (AuthorId) REFERENCES Usuario(IdUsuario)
);

-- Recrear índices
CREATE INDEX idx_blog_author ON BlogPost(AuthorId);
CREATE INDEX idx_blog_category ON BlogPost(CategoryId);
CREATE INDEX idx_blog_published ON BlogPost(IsPublished);
CREATE INDEX idx_blog_slug ON BlogPost(Slug);
CREATE INDEX idx_blog_featured ON BlogPost(IsFeatured);
CREATE INDEX idx_blog_created ON BlogPost(CreatedAt);
")

